To find the cut vertices and bridges in the given graph, we can use Tarjan's algorithm. Here's the implementation of Tarjan's algorithm to find the cut vertices and bridges:

```python
def tarjan(graph):
    time = 0
    visited = {}
    low = {}
    cut_vertices = set()
    bridges = set()

    def dfs(node, parent=None):
        nonlocal time
        visited[node] = True
        low[node] = time
        time += 1
        children = 0

        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if not visited.get(neighbor, False):
                children += 1
                dfs(neighbor, node)
                low[node] = min(low[node], low[neighbor])

                if parent is None and children > 1:
                    cut_vertices.add(node)
                if parent is not None and low[neighbor] >= visited[node]:
                    cut_vertices.add(node)
                if low[neighbor] > visited[node]:
                    bridges.add((node, neighbor))
            else:
                low[node] = min(low[node], visited[neighbor])

    for node in graph:
        if not visited.get(node, False):
            dfs(node)

    return cut_vertices, bridges

graph = {
    'A': ['B', 'C', 'E'],
    'B': ['A', 'D', 'E'],
    'C': ['A', 'F', 'G'],
    'D': ['B'],
    'E': ['A', 'B', 'F'],
    'F': ['C', 'E'],
    'G': ['C']
}

cut_vertices, bridges = tarjan(graph)
print("Cut vertices:", cut_vertices)
print("Bridges:", bridges)
```

