To solve this problem using the differential evolution algorithm, we will follow these steps:

1. Initialize the population.
2. Mutate and crossover to create a trial vector.
3. Perform selection.
4. Repeat steps 2-3 for 100 generations.
5. Find the maximum value of f(x) and the corresponding value of x.

Here's a Python implementation of the differential evolution algorithm for this problem:

```python
import numpy as np

def f(x):
    return np.sin(x)

def initialize_population(pop_size, lower_bound, upper_bound):
    return lower_bound + (upper_bound - lower_bound) * np.random.rand(pop_size, 1)

def mutate(pop, F):
    pop_size = len(pop)
    mutated = np.zeros_like(pop)
    for i in range(pop_size):
        a, b, c = pop[np.random.choice(pop_size, 3, replace=False)]
        mutated[i] = a + F * (b - c)
    return mutated

def crossover(pop, mutated, CR):
    pop_size, dim = pop.shape
    trial = np.zeros_like(pop)
    for i in range(pop_size):
        for j in range(dim):
            if np.random.rand() < CR:
                trial[i, j] = mutated[i, j]
            else:
                trial[i, j] = pop[i, j]
    return trial

def select(pop, trial):
    return np.where(f(trial) > f(pop), trial, pop)

def differential_evolution(pop_size, F, CR, generations, lower_bound, upper_bound):
    pop = initialize_population(pop_size, lower_bound, upper_bound)
    for _ in range(generations):
        mutated = mutate(pop, F)
        trial = crossover(pop, mutated, CR)
        pop = select(pop, trial)
    max_idx = np.argmax(f(pop))
    return pop[max_idx], f(pop[max_idx])

pop_size = 50
F = 0.5
CR = 0.8
generations = 100
lower_bound = -5
upper_bound = 5

x_max, f_max = differential_evolution(pop_size, F, CR, generations, lower_bound, upper_bound)
print(f"Maximum value of f(x): {f_max}")
print(f"Corresponding value of x: {x_max[0]}")
```

Please note that the results may vary slightly due to the random nature of the algorithm. Run the code to find the maximum value of f(x) and the corresponding value of x where it occurs.

