Here's a MATLAB program to solve the given problem using linear triangular elements:

```MATLAB
function poisson_fem
    % Define the mesh size
    n = 20;
    [p, t] = create_mesh(n);

    % Assemble the stiffness matrix and load vector
    [K, F] = assemble(p, t);

    % Apply boundary conditions
    [K, F] = apply_boundary_conditions(K, F, p);

    % Solve the linear system
    u = K \ F;

    % Plot the solution
    plot_solution(p, t, u);
end

function [p, t] = create_mesh(n)
    [p, t] = square_mesh(n);
end

function [K, F] = assemble(p, t)
    N = size(p, 1);
    K = sparse(N, N);
    F = zeros(N, 1);

    for i = 1:size(t, 1)
        nodes = t(i, 1:3);
        vertices = p(nodes, :);
        [Ke, Fe] = element_stiffness_matrix(vertices);
        K(nodes, nodes) = K(nodes, nodes) + Ke;
        F(nodes) = F(nodes) + Fe;
    end
end

function [Ke, Fe] = element_stiffness_matrix(vertices)
    area = polyarea(vertices(:, 1), vertices(:, 2));
    B = [vertices(2, 2) - vertices(3, 2), vertices(3, 2) - vertices(1, 2), vertices(1, 2) - vertices(2, 2);
         vertices(3, 1) - vertices(2, 1), vertices(1, 1) - vertices(3, 1), vertices(2, 1) - vertices(1, 1)];
    C = B' * B;
    Ke = (1 / (4 * area)) * C;

    f = @(x, y) 2 * (x^2 - x) * (y^2 - y);
    Fe = (area / 3) * arrayfun(f, vertices(:, 1), vertices(:, 2));
end

function [K, F] = apply_boundary_conditions(K, F, p)
    boundary_nodes = find(p(:, 1) == 0 | p(:, 1) == 1 | p(:, 2) == 0 | p(:, 2) == 1);
    K(boundary_nodes, :) = 0;
    K(:, boundary_nodes) = 0;
    F(boundary_nodes) = 0;
    K(boundary_nodes, boundary_nodes) = 1;
end

function plot_solution(p, t, u)
    trisurf(t, p(:, 1), p(:, 2), u);
    shading interp;
    colormap jet;
    colorbar;
    xlabel('x');
    ylabel('y');
    zlabel('u(x, y)');
    title('Solution of the Poisson equation using FEM');
end
```

To run the program, save it as a file named `poisson_fem.m` and execute it in MATLAB by typing `poisson_fem` in the command window. The program will generate a surface plot of the solution using the `surf` function.

