Here's a simple implementation of the bat algorithm in MATLAB to find the minimum value and corresponding x for the given function f(x) = x^2 - 10x + 25:

```MATLAB
% Objective function
f = @(x) x^2 - 10*x + 25;

% Parameters
n_bats = 10;
n_iterations = 100;
x_min = -10;
x_max = 20;
v_min = -1;
v_max = 1;

% Initialization
x = x_min + (x_max - x_min) * rand(n_bats, 1);
v = v_min + (v_max - v_min) * rand(n_bats, 1);
f_values = f(x);
[best_f_value, best_idx] = min(f_values);
x_best = x(best_idx);

% Bat algorithm
for t = 1:n_iterations
    for i = 1:n_bats
        f_random = rand();
        v(i) = v(i) + (x_best - x(i)) * f_random;
        x(i) = x(i) + v(i);

        % Boundary check
        if x(i) < x_min
            x(i) = x_min;
        elseif x(i) > x_max
            x(i) = x_max;
        end

        % Update local best
        f_value = f(x(i));
        if f_value < f_values(i)
            f_values(i) = f_value;
        end

        % Update global best
        if f_value < best_f_value
            best_f_value = f_value;
            x_best = x(i);
        end
    end
end

% Results
fprintf('Minimum value: %.4f\n', best_f_value);
fprintf('Corresponding x: %.4f\n', x_best);
```

